/**
 * Who Yitz is. Feeds the home page, /about, llms.txt, the MCP server and the Person schema.
 *
 * This interface was referenced by `Config`'s JSON-Schema
 * via the `definition` "profile".
 */
export interface Profile {
  id: number;
  name: string;
  givenName?: string | null;
  familyName?: string | null;
  /**
   * For schema.org jobTitle and llms.txt. Roles, never a job search.
   */
  jobTitles: string[];
  /**
   * The home page H1. Two to ten words.
   */
  headline: string;
  /**
   * Home page lead: two or three sentences in the first person.
   */
  intro: string;
  /**
   * Third-person summary for llms.txt, agents and schema description.
   */
  summary: string;
  /**
   * The /about page body.
   */
  about?: {
    root: {
      type: string;
      children: {
        type: any;
        version: number;
        [k: string]: unknown;
      }[];
      direction: ('ltr' | 'rtl') | null;
      format: 'left' | 'start' | 'center' | 'right' | 'end' | 'justify' | '';
      indent: number;
      version: number;
    };
    [k: string]: unknown;
  } | null;
  /**
   * One professional headshot, the same as LinkedIn.
   */
  photo?: (number | null) | Media;
  /**
   * Short, checkable facts for /about and agents. No year counts that read as an age.
   */
  highlights?:
    | {
        text: string;
        id?: string | null;
      }[]
    | null;
  /**
   * Only Vouch Networks, Charter and Quartz are named. Everything else uses a generic label.
   */
  experience?:
    | {
        display: 'named' | 'generic';
        schemaRole: 'worksFor' | 'alumniOf' | 'none';
        orgName?: string | null;
        orgUrl?: string | null;
        orgWikidataId?: string | null;
        /**
         * e.g. https://www.vouchnetworks.org/#organization
         */
        orgId?: string | null;
        /**
         * e.g. "a logistics startup".
         */
        genericLabel?: string | null;
        title: string;
        /**
         * YYYY or YYYY-MM
         */
        start?: string | null;
        /**
         * Empty for current
         */
        end?: string | null;
        summary?: string | null;
        id?: string | null;
      }[]
    | null;
  education?:
    | {
        name: string;
        field?: string | null;
        url?: string | null;
        wikidataId?: string | null;
        id?: string | null;
      }[]
    | null;
  /**
   * homeLocation in the schema. The first is primary.
   */
  locations?:
    | {
        city: string;
        region?: string | null;
        country?: string | null;
        wikidataId?: string | null;
        id?: string | null;
      }[]
    | null;
  languages?:
    | {
        name: string;
        code: string;
        id?: string | null;
      }[]
    | null;
  /**
   * Professional profiles of the same person, such as LinkedIn and GitHub. Encyclopedia and entertainment hosts are refused.
   */
  sameAs?:
    | {
        url: string;
        id?: string | null;
      }[]
    | null;
  availability?: {
    status?: ('open' | 'selective' | 'not-looking' | 'unspecified') | null;
    /**
     * e.g. "AI technical lead", "Senior full-stack engineer".
     */
    roles?: string[] | null;
    /**
     * e.g. "Full-time", "Contract".
     */
    engagements?: string[] | null;
    /**
     * e.g. "New York", "Columbus", "Remote (US)".
     */
    workLocations?: string[] | null;
    note?: string | null;
  };
  updatedAt?: string | null;
  createdAt?: string | null;
}
